/**
 * Lodash Utils Plus - Enhanced utility functions
 * @module lodash-utils-plus
 */

const _ = require('lodash');

/**
 * Deep clone with circular reference handling
 * @param {*} value - The value to clone
 * @returns {*} The cloned value
 */
function deepClone(value) {
  return _.cloneDeepWith(value, (val) => {
    if (_.isPlainObject(val) || _.isArray(val)) {
      return undefined; // Let lodash handle it
    }
    return val;
  });
}

/**
 * Memoize with automatic cache size management
 * @param {Function} func - Function to memoize
 * @param {number} [maxSize=100] - Maximum cache size
 * @returns {Function} Memoized function
 */
function smartMemoize(func, maxSize = 100) {
  const memoized = _.memoize(func);
  const originalCache = memoized.cache;

  memoized.cache = {
    get: (key) => originalCache.get(key),
    set: (key, value) => {
      if (originalCache.size >= maxSize) {
        originalCache.clear();
      }
      originalCache.set(key, value);
    },
    has: (key) => originalCache.has(key),
    delete: (key) => originalCache.delete(key),
    clear: () => originalCache.clear(),
    size: 0
  };

  return memoized;
}

module.exports = {
  deepClone,
  smartMemoize,
  ..._
};
