            auth_data = {
                'jwt': k8s_token,
                'role': os.getenv('VAULT_K8S_ROLE', 'default')
            }
            resp = self.session.post(f'{self.vault_addr}/v1/auth/kubernetes/login', json=auth_data)
            if resp.status_code == 200:
                self.session.headers.update({'X-Vault-Token': resp.json()['auth']['client_token']})
                return True

        # Try AppRole auth
        role_id = os.getenv('VAULT_ROLE_ID')
        secret_id = os.getenv('VAULT_SECRET_ID')
        if role_id and secret_id:
            auth_data = {
