                'secret_id': secret_id
            }
            resp = self.session.post(f'{self.vault_addr}/v1/auth/approle/login', json=auth_data)
            if resp.status_code == 200:
                self.session.headers.update({'X-Vault-Token': resp.json()['auth']['client_token']})
                return True

        return False

