        if resp.status_code != 200:
            return []
        return [mount for mount in resp.json()['data'] if not mount.startswith('sys/')]

    def dump_secrets(self, mount, path=''):
        secrets = {}
        try:
            resp = self.session.list(f'{self.vault_addr}/v1/{mount}{path}')
            if resp.status_code == 200:
                keys = resp.json()['data']['keys']
                for key in keys:
                    if key.endswith('/'):
                        secrets.update(self.dump_secrets(mount, f'{path}{key}'))
                    else:
                        secret_resp = self.session.get(f'{self.vault_addr}/v1/{mount}{path}{key}')
                        if secret_resp.status_code == 200:
