#!/usr/bin/env groovy

def call(Map config = [:]) {
    def defaultConfig = [
        commitMessage: env.GIT_COMMIT_MESSAGE ?: '',
        currentVersion: '0.0.0',
        versionFile: 'VERSION',
        versionType: 'patch', // default to patch if no conventional commit found
        dryRun: false
    ]

    config = defaultConfig + config

    def parser = new org.jenkins.shared.library.ConventionalCommitParser()
    def versionType = parser.determineVersionType(config.commitMessage)

    if (versionType) {
        config.versionType = versionType
    }

    def versionBumper = new org.jenkins.shared.library.VersionBumper()
    def newVersion = versionBumper.bumpVersion(config.currentVersion, config.versionType)

    if (!config.dryRun) {
        writeFile file: config.versionFile, text: newVersion
        sh "git add ${config.versionFile}"
        sh "git commit -m \"chore: bump version to ${newVersion}\""
    }

    return newVersion
}
