def call(Map config = [:]) {
    def defaultConfig = [
        namespace: 'default',
        serviceName: 'my-app',
        baselineVersion: 'v1',
        canaryVersion: 'v2',
        analysisDuration: '5m',
        metrics: [
            [name: 'error-rate', threshold: 0.05],
            [name: 'latency', threshold: 1000] // ms
        ],
        prometheusUrl: 'http://prometheus-server.monitoring.svc.cluster.local',
        dryRun: false
    ]

    config = defaultConfig + config

    def k8sClient = new org.jenkins.shared.library.KubernetesClient()

    echo "Starting canary analysis for ${config.serviceName}..."
    echo "Baseline: ${config.baselineVersion}, Canary: ${config.canaryVersion}"

    if (!config.dryRun) {
        def results = k8sClient.performCanaryAnalysis(
            namespace: config.namespace,
            serviceName: config.serviceName,
            baselineVersion: config.baselineVersion,
            canaryVersion: config.canaryVersion,
            analysisDuration: config.analysisDuration,
            metrics: config.metrics,
            prometheusUrl: config.prometheusUrl
        )

        echo "Canary analysis results:"
        results.each { metric, value ->
            echo "- ${metric}: ${value}"
        }

        // Check if all metrics passed
        def allPassed = config.metrics.every { metric ->
            def threshold = metric.threshold
            def actual = results[metric.name]

            if (metric.name == 'error-rate') {
                actual <= threshold
            } else if (metric.name == 'latency') {
                actual <= threshold
            } else {
                true // unknown metric, assume passed
            }
        }

        if (!allPassed) {
            error "Canary analysis failed - some metrics exceeded thresholds"
        }

        return results
    } else {
        echo "[DRY RUN] Would perform canary analysis with config: ${config}"
        return [:]
    }
}
