#!/usr/bin/env groovy

def call(Map config = [:]) {
    def defaultConfig = [
        auditEndpoint: 'https://jenkins-audit.internal/health',
        auditToken: null,
        testConnectivity: true,
        dryRun: false
    ]

    config = defaultConfig + config

    def checker = new org.jenkins.shared.library.CredentialHealthChecker()
    def auditLogger = new org.jenkins.shared.library.AuditLogger()

    def credentials = checker.getAllCredentials()

    def results = []
    def healthy = true

    credentials.each { cred ->
        def result = [
            id: cred.id,
            description: cred.description,
            type: cred.typeName,
            expired: false,
            connectivity: 'not_tested',
            healthy: false
        ]

        try {
            // Check expiration
            if (cred.hasProperty('expiration') && cred.expiration) {
                def expirationDate = new Date(cred.expiration)
                result.expired = expirationDate.before(new Date())
            }

            // Test connectivity if enabled
            if (config.testConnectivity && cred.hasProperty('testConnectivity')) {
                result.connectivity = cred.testConnectivity() ? 'success' : 'failed'
            }

            result.healthy = !result.expired && (result.connectivity != 'failed')
        } catch (Exception e) {
            result.error = e.message
            result.healthy = false
        }

        results << result

        if (!result.healthy) {
            healthy = false
        }
    }

    if (!config.dryRun) {
        // Log to audit endpoint
        withCredentials([[
            $class: 'StringBinding',
            credentialsId: config.auditToken,
            variable: 'AUDIT_TOKEN'
        ]]) {
            auditLogger.logToAuditEndpoint(
                endpoint: config.auditEndpoint,
                token: env.AUDIT_TOKEN,
                data: [
                    timestamp: new Date().format("yyyy-MM-dd'T'HH:mm:ss.SSSZ"),
                    credentials: results.collect { [
                        id: it.id,
                        type: it.type,
                        healthy: it.healthy,
                        expired: it.expired,
                        connectivity: it.connectivity
                    ] }
                ]
            )
        }
    } else {
        echo "[DRY RUN] Would log credential health to ${config.auditEndpoint}"
    }

    if (!healthy) {
        error "Some credentials are unhealthy. Check the logs for details."
    }

    return results
}
